<style>
.admin-management-page{direction:rtl;color:#183c32}.admin-page-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:1rem}.admin-page-heading span{color:#738078;font-size:.85rem}.admin-page-heading h1{margin:.2rem 0;font-size:1.45rem}.admin-page-heading>button,.admin-actions button,.admin-table-row>button,.admin-inline-form button,.admin-simple-row button,.admin-settings-form button{border:0;border-radius:.55rem;background:#183c32;color:#fff;padding:.55rem .8rem;cursor:pointer}.admin-table{border:1px solid #e1e8e4;border-radius:.75rem;background:#fff;overflow:hidden}.admin-table-head,.admin-table-row{display:grid;grid-template-columns:minmax(180px,1.4fr) minmax(180px,1fr) minmax(180px,.8fr);align-items:center;gap:1rem;padding:.75rem 1rem}.admin-table-head{background:#f7faf8;color:#6b786f;font-size:.82rem}.admin-table-row{border-top:1px solid #edf1ee}.admin-table-row>div:first-child,.admin-table-row>div:nth-child(2){display:grid;gap:.25rem}.admin-table-row small{color:#75827c}.admin-table-row select,.admin-actions input,.admin-inline-form input,.admin-settings-form input,.admin-settings-form textarea{width:100%;border:1px solid #d6dfda;border-radius:.45rem;background:#fff;padding:.55rem;color:#183c32}.admin-actions{display:flex;align-items:center;gap:.45rem}.admin-actions details{display:grid}.admin-actions details div{display:grid;gap:.35rem}.status-pending{color:#9a6a17}.status-approved{color:#267348}.status-rejected{color:#a33c32}.admin-empty{text-align:center;color:#75827c;padding:2rem}.admin-grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.admin-grid section{border:1px solid #e1e8e4;border-radius:.75rem;background:#fff;padding:1rem}.admin-inline-form{display:flex;gap:.4rem;margin:.75rem 0}.admin-simple-row{display:flex;justify-content:space-between;border-top:1px solid #edf1ee;padding:.65rem 0}.admin-report-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem}.admin-report-metrics article{border:1px solid #e1e8e4;border-radius:.75rem;background:#fff;padding:1rem;display:grid}.admin-report-metrics strong{font-size:1.35rem}.admin-settings-form{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem;border:1px solid #e1e8e4;border-radius:.75rem;background:#fff;padding:1rem}.admin-settings-form label{display:grid;gap:.35rem}.admin-settings-form label:nth-last-child(-n+2){grid-column:1/-1}.admin-table-head-users,.admin-table-row-users{grid-template-columns:minmax(220px,1.4fr) 1fr 140px 1fr}@media(max-width:900px){.admin-table-head{display:none}.admin-table-row,.admin-table-head-users,.admin-table-row-users{grid-template-columns:1fr}.admin-grid,.admin-report-metrics,.admin-settings-form{grid-template-columns:1fr}.admin-settings-form label:nth-last-child(-n+2){grid-column:auto}}
</style>
{{-- الأنماط المشتركة لصفحات إدارة المنصة والجداول والنماذج والحالات الفارغة. --}}
